import{_ as o,o as a,c as n,a4 as t}from"./chunks/framework.DPwo9VAo.js";const g=JSON.parse('{"title":"Tra cứu API: Functions (Hàm chức năng & Services)","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/functions.md","filePath":"api-reference/functions.md","lastUpdated":1795338762000}'),r={name:"api-reference/functions.md"};function i(s,e,p,m,d,c){return a(),n("div",null,e[0]||(e[0]=[t('<h1 id="tra-cuu-api-functions-ham-chuc-nang-services" tabindex="-1">Tra cứu API: Functions (Hàm chức năng &amp; Services) <a class="header-anchor" href="#tra-cuu-api-functions-ham-chuc-nang-services" aria-label="Permalink to &quot;Tra cứu API: Functions (Hàm chức năng &amp; Services)&quot;">​</a></h1><p>Danh sách các hàm tiện ích và API chức năng phổ biến nhất trong hệ sinh thái.</p><hr><h2 id="_1-truy-xuat-đang-ky-map-platform-hungpvq-map-core" tabindex="-1">1. Truy xuất &amp; Đăng ký Map Platform (<code>@hungpvq/map-core</code>) <a class="header-anchor" href="#_1-truy-xuat-đang-ky-map-platform-hungpvq-map-core" aria-label="Permalink to &quot;1. Truy xuất &amp; Đăng ký Map Platform (`@hungpvq/map-core`)&quot;">​</a></h2><h3 id="getmap-mapid-string-mapsimple-undefined" tabindex="-1"><code>getMap(mapId: string): MapSimple | undefined</code> <a class="header-anchor" href="#getmap-mapid-string-mapsimple-undefined" aria-label="Permalink to &quot;`getMap(mapId: string): MapSimple | undefined`&quot;">​</a></h3><p>Truy xuất đối tượng <code>MapSimple</code> tương ứng với <code>mapId</code>.</p><ul><li><strong>Tham số</strong>: <code>mapId</code> (chuỗi định danh bản đồ).</li><li><strong>Trả về</strong>: Đối tượng <code>MapSimple</code> hoặc <code>undefined</code> nếu bản đồ chưa sẵn sàng.</li></ul><h3 id="subscribemapready-mapid-string-cb-map-mapsimple-void-void" tabindex="-1"><code>subscribeMapReady(mapId: string, cb: (map: MapSimple) =&gt; void): () =&gt; void</code> <a class="header-anchor" href="#subscribemapready-mapid-string-cb-map-mapsimple-void-void" aria-label="Permalink to &quot;`subscribeMapReady(mapId: string, cb: (map: MapSimple) =&gt; void): () =&gt; void`&quot;">​</a></h3><p>Lắng nghe sự kiện bản đồ sẵn sàng. Nếu bản đồ đã tải xong từ trước, callback sẽ được gọi ngay lập tức.</p><ul><li><strong>Trả về</strong>: Hàm <code>unsubscribe()</code> để hủy lắng nghe.</li></ul><h3 id="registermapaccessor-mapid-string-accessor-mapsimple-undefined-options-registermapplatformoptions-mapplatformregistration" tabindex="-1"><code>registerMapAccessor(mapId: string, accessor: () =&gt; MapSimple | undefined, options?: RegisterMapPlatformOptions): MapPlatformRegistration</code> <a class="header-anchor" href="#registermapaccessor-mapid-string-accessor-mapsimple-undefined-options-registermapplatformoptions-mapplatformregistration" aria-label="Permalink to &quot;`registerMapAccessor(mapId: string, accessor: () =&gt; MapSimple | undefined, options?: RegisterMapPlatformOptions): MapPlatformRegistration`&quot;">​</a></h3><p>Đăng ký hàm lấy instance của một bản đồ vào platform registry.</p><hr><h2 id="_2-tao-xu-ly-dataset-hungpvq-map-dataset-geojson" tabindex="-1">2. Tạo &amp; Xử lý Dataset (<code>@hungpvq/map-dataset/geojson</code>) <a class="header-anchor" href="#_2-tao-xu-ly-dataset-hungpvq-map-dataset-geojson" aria-label="Permalink to &quot;2. Tạo &amp; Xử lý Dataset (`@hungpvq/map-dataset/geojson`)&quot;">​</a></h2><h3 id="creategeojsondataset-options-geojsondatasetoption-promise-idataset" tabindex="-1"><code>createGeoJsonDataset(options: GeojsonDatasetOption): Promise&lt;IDataset&gt;</code> <a class="header-anchor" href="#creategeojsondataset-options-geojsondatasetoption-promise-idataset" aria-label="Permalink to &quot;`createGeoJsonDataset(options: GeojsonDatasetOption): Promise&lt;IDataset&gt;`&quot;">​</a></h3><p>Tạo nhanh một Dataset dạng lá (<code>DatasetLeaf</code>) từ đối tượng hoặc URL GeoJSON.</p><ul><li><strong>Tham số</strong>: <code>options</code> chứa <code>id</code>, <code>name</code>, <code>data</code>, <code>color</code>, <code>opacity</code>.</li><li><strong>Trả về</strong>: Đối tượng <code>IDataset</code> đã cấu hình sẵn source và layer.</li></ul><h3 id="loadgeojsonfileasync-file-file-promise-geojson-featurecollection" tabindex="-1"><code>loadGeojsonFileAsync(file: File): Promise&lt;GeoJSON.FeatureCollection&gt;</code> <a class="header-anchor" href="#loadgeojsonfileasync-file-file-promise-geojson-featurecollection" aria-label="Permalink to &quot;`loadGeojsonFileAsync(file: File): Promise&lt;GeoJSON.FeatureCollection&gt;`&quot;">​</a></h3><p>Sử dụng Web Worker chạy ngầm để đọc và phân tích file <code>.geojson</code>, <code>.json</code>, <code>.kml</code>, <code>.zip</code> (shapefile) mà không làm đơ giao diện.</p><h3 id="reprojectgeojsonasync-data-geojson-geojson-fromepsg-string-toepsg-string-promise-geojson-geojson" tabindex="-1"><code>reprojectGeojsonAsync(data: GeoJSON.GeoJSON, fromEpsg: string, toEpsg: string): Promise&lt;GeoJSON.GeoJSON&gt;</code> <a class="header-anchor" href="#reprojectgeojsonasync-data-geojson-geojson-fromepsg-string-toepsg-string-promise-geojson-geojson" aria-label="Permalink to &quot;`reprojectGeojsonAsync(data: GeoJSON.GeoJSON, fromEpsg: string, toEpsg: string): Promise&lt;GeoJSON.GeoJSON&gt;`&quot;">​</a></h3><p>Chuyển đổi hệ tọa độ của đối tượng GeoJSON trên Web Worker sử dụng Proj4.</p><hr><h2 id="_3-đieu-khien-view-hinh-hoc-hungpvq-map-core" tabindex="-1">3. Điều khiển View &amp; Hình học (<code>@hungpvq/map-core</code>) <a class="header-anchor" href="#_3-đieu-khien-view-hinh-hoc-hungpvq-map-core" aria-label="Permalink to &quot;3. Điều khiển View &amp; Hình học (`@hungpvq/map-core`)&quot;">​</a></h2><h3 id="fitbounds-map-mapsimple-bbox-number-number-number-number-options-fitboundsoptions-void" tabindex="-1"><code>fitBounds(map: MapSimple, bbox: [number, number, number, number], options?: FitBoundsOptions): void</code> <a class="header-anchor" href="#fitbounds-map-mapsimple-bbox-number-number-number-number-options-fitboundsoptions-void" aria-label="Permalink to &quot;`fitBounds(map: MapSimple, bbox: [number, number, number, number], options?: FitBoundsOptions): void`&quot;">​</a></h3><p>Tự động căn chỉnh góc nhìn của bản đồ để bao trọn hộp tọa độ <code>[minLng, minLat, maxLng, maxLat]</code>.</p><h3 id="degtodms-deg-number-d-number-m-number-s-number" tabindex="-1"><code>degToDms(deg: number): { d: number, m: number, s: number }</code> <a class="header-anchor" href="#degtodms-deg-number-d-number-m-number-s-number" aria-label="Permalink to &quot;`degToDms(deg: number): { d: number, m: number, s: number }`&quot;">​</a></h3><p>Chuyển đổi độ thập phân sang Độ-Phút-Giây.</p><h3 id="dmstodeg-d-number-m-number-s-number-number" tabindex="-1"><code>dmsToDeg(d: number, m: number, s: number): number</code> <a class="header-anchor" href="#dmstodeg-d-number-m-number-s-number-number" aria-label="Permalink to &quot;`dmsToDeg(d: number, m: number, s: number): number`&quot;">​</a></h3><p>Chuyển đổi Độ-Phút-Giây sang độ thập phân.</p><hr><h2 id="_4-theme-đa-ngon-ngu-hungpvq-map-core" tabindex="-1">4. Theme &amp; Đa ngôn ngữ (<code>@hungpvq/map-core</code>) <a class="header-anchor" href="#_4-theme-đa-ngon-ngu-hungpvq-map-core" aria-label="Permalink to &quot;4. Theme &amp; Đa ngôn ngữ (`@hungpvq/map-core`)&quot;">​</a></h2><h3 id="bootstrapmaptheme-mode-mapthememode-options-applymapthemeoptions-void" tabindex="-1"><code>bootstrapMapTheme(mode: MapThemeMode, options?: ApplyMapThemeOptions): void</code> <a class="header-anchor" href="#bootstrapmaptheme-mode-mapthememode-options-applymapthemeoptions-void" aria-label="Permalink to &quot;`bootstrapMapTheme(mode: MapThemeMode, options?: ApplyMapThemeOptions): void`&quot;">​</a></h3><p>Áp dụng theme màu cho toàn bộ ứng dụng hoặc riêng cho một container map.</p><h3 id="bootstrapmaplanguage-lang-en-vi-void" tabindex="-1"><code>bootstrapMapLanguage(lang: &#39;en&#39; | &#39;vi&#39;): void</code> <a class="header-anchor" href="#bootstrapmaplanguage-lang-en-vi-void" aria-label="Permalink to &quot;`bootstrapMapLanguage(lang: &#39;en&#39; | &#39;vi&#39;): void`&quot;">​</a></h3><p>Thay đổi ngôn ngữ hiển thị của toàn bộ các control và thông báo trong hệ thống.</p>',35)]))}const u=o(r,[["render",i]]);export{g as __pageData,u as default};
